// Extract event data from FB/IG webhook
// Use webhook node reference to get raw body (Config Set node would overwrite $input)
const body = $('🔔 Webhook: FB/IG Interacción').item.json.body || {};

// Extract page_id from entry — used for multi-tenant company resolution via G54
const pageId = String((body.entry || [])[0]?.id || '');

let plataforma = 'facebook';
let tipo = 'comentario'; // comentario | dm
let mensaje = '';
let comentarioId = '';
let postId = '';
let usuarioId = '';
let usuarioNombre = '';
let mediaId = '';

const entry = (body.entry || [])[0] || {};

// Los DM reales de Meta (FB Messenger e Instagram DM) llegan por entry.messaging[],
// no por entry.changes — mismo formato en ambas plataformas, confirmado contra el
// extractor ya probado en producción de Sales AI Motor. Se revisa primero, antes
// que el camino de comentarios (que sí usa entry.changes correctamente).
const messagingEvent = (entry.messaging || [])[0];
if (messagingEvent && messagingEvent.message) {
  tipo = 'dm';
  plataforma = body.object === 'instagram' ? 'instagram' : 'facebook';
  usuarioId = messagingEvent.sender?.id || '';
  mensaje = messagingEvent.message?.text || '';
  comentarioId = messagingEvent.message?.mid || '';
} else if (body.object === 'page') {
  // Facebook page feed (comments on posts)
  const change = (entry.changes || [])[0] || {};
  const val = change.value || {};
  plataforma = 'facebook';

  if (change.field === 'messages') {
    // FB Messenger DM (formato legacy vía changes, por si Meta lo manda así en algún caso)
    tipo = 'dm';
    const msg = (val.messages || [])[0] || {};
    mensaje = msg.text || '';
    usuarioId = val.sender?.id || '';
    comentarioId = msg.mid || '';
  } else {
    // FB comment on post
    tipo = 'comentario';
    mensaje = val.message || '';
    comentarioId = val.comment_id || val.id || '';
    postId = val.post_id || '';
    usuarioId = val.from?.id || '';
    usuarioNombre = val.from?.name || '';
  }
} else if (body.object === 'instagram') {
  // Instagram (comments on media)
  const change = (entry.changes || [])[0] || {};
  const val = change.value || {};
  plataforma = 'instagram';

  if (change.field === 'messages') {
    tipo = 'dm';
    const msg = (val.messages || [])[0] || {};
    mensaje = msg.text?.body || msg.text || '';
    usuarioId = val.sender?.id || '';
    comentarioId = msg.mid || '';
  } else {
    tipo = 'comentario';
    mensaje = val.text || val.message || '';
    comentarioId = val.id || '';
    mediaId = val.media?.id || '';
    usuarioId = val.from?.id || '';
    usuarioNombre = val.from?.username || '';
  }
}

// Skip if no message or if it's our own reply (avoid loops)
if (!mensaje.trim()) {
  throw new Error('SKIP: empty message');
}

return [{ json: {
  plataforma,
  tipo,
  mensaje,
  comentarioId,
  postId,
  mediaId,
  usuarioId,
  usuarioNombre,
  pageId
}}];

// Read company_id from webhook query param (?company=N)
// Each client registers: .../webhook/community-ai-g54?company=N
const query = $('🔔 Webhook: FB/IG Interacción').item.json.query || {};
const queryCompanyId = String(query.company || '');
// pageId already extracted by previous node for future API resolution
const pageId = $('🔍 Extraer Evento FB/IG').item.json.pageId || '';
return [{ json: { queryCompanyId, pageId } }];

const config = $('⚙️ Config Growth54').item.json;
const resolver = $('🔍 Resolver Empresa').item.json;
const pageData = $('🔍 Obtener Config Página (G54)').item.json;

// company_id: de la API de páginas > query param > fallback CE
const company_id = String(pageData.company_id || resolver.queryCompanyId || '');

// Tokens: preferir el Page Access Token real (intercambiado desde el token de G54,
// necesario porque el token guardado en G54 es de usuario, no de página — Meta rechaza
// publicar comentarios/DMs con un token de usuario aunque sí sirva para otras acciones).
let fb_access_token = pageData.fb_access_token || '';
try {
  const exchanged = $('🔑 Intercambiar Page Token (FB)').item.json;
  if (exchanged && exchanged.access_token) fb_access_token = exchanged.access_token;
} catch (e) { /* si falló el intercambio, seguimos con el token original de G54 */ }

const ig_user_id = pageData.ig_user_id || '';
const ig_access_token = pageData.ig_access_token || '';

return [{ json: {
  G54_BASE_URL: config.G54_BASE_URL,
  G54_N8N_TOKEN: config.G54_N8N_TOKEN,
  G54_AGENT_TOKEN: config.G54_AGENT_TOKEN,
  G54_COMPANY_ID: company_id,
  FB_PAGE_ID: resolver.pageId || '',
  FB_ACCESS_TOKEN: fb_access_token,
  IG_USER_ID: ig_user_id,
  IG_ACCESS_TOKEN: ig_access_token,
  GROQ_API_KEY: config.GROQ_API_KEY,
  WA_LINK: config.WA_LINK || ''
}}];

const config = $('🏢 Aplicar Config Empresa').item.json;
const evento = $('🔍 Extraer Evento FB/IG').item.json;
const empresaRaw = $('📊 Obtener Perfil Empresa').item.json;
const empresa = empresaRaw.data || empresaRaw || {};
const estRaw = $('🎯 Obtener Estrategia RRSS').item?.json || {};
const estrategia = estRaw.data || estRaw || {};

const postRaw = $('📄 Obtener Contenido del Post').item?.json || {};
const contenidoPost = postRaw.message || postRaw.story || '';

const nombre_empresa = empresa.name || empresa.nombre || '';
const descripcion = empresa.description || empresa.descripcion || '';
const tono = estrategia.tono || 'profesional, cercano y directo';
const wa_link = config.WA_LINK || '';

// Canal de escalada: WhatsApp si la empresa tiene link configurado, si no, DM en la misma plataforma — nunca un canal fijo
const canalEscalada = wa_link ? `WhatsApp (link EXACTO: ${wa_link})` : 'mensaje privado (DM) en esta misma plataforma';
const siguientePasoValor = wa_link ? 'whatsapp' : 'dm';

const seccionPost = contenidoPost
  ? `\nCONTEXTO DEL POST COMENTADO:\n${contenidoPost}\n`
  : '';

// Personalidad y conocimiento real del negocio (system_prompt configurado por el cliente en
// Ventas › Bot / Asistente) — mismo dato que ya usan WhatsApp y Telegram. Se antepone como base
// de tono/datos reales; las reglas de comportamiento en público (no calificar, invitar a DM/WA)
// se mantienen siempre, sin importar si hay o no un prompt real configurado.
let seccionPersonalidad = '';
try {
  const botConfigRaw = $('⚙️ G54: Bot Config').first().json;
  const bc = botConfigRaw?.data || botConfigRaw;
  if (bc && bc.system_prompt) {
    seccionPersonalidad = `PERSONALIDAD Y CONOCIMIENTO DEL NEGOCIO (tono real y datos reales de la empresa — úsalo como base):
${bc.system_prompt}

---

`;
  }
} catch (e) { /* sin bot-config disponible, se sigue con el prompt genérico de siempre */ }

const promptSistema = `${seccionPersonalidad}Actúa como un Community Manager experto en conversión, integrando SEO, AEO y GEO.

Empresa: ${nombre_empresa}
Descripción: ${descripcion}
Tono de marca: ${tono}
Canal de escalada: ${canalEscalada}

Tu función es:
- responder con claridad (AEO)
- detectar intención del usuario
- calificar el lead
- llevar la conversación FUERA del comentario público, hacia ${canalEscalada}, lo antes posible

Debes:
1. Identificar la intención: informacional, comercial o transaccional
2. Dar una micro-respuesta útil y breve (máximo 1 oración) que demuestre que entendiste lo que pidió — sin resolverlo por completo en el comentario
3. Invitar a continuar por ${canalEscalada} — esto va SIEMPRE, en cada respuesta, sin excepción, incluso en el primer mensaje
4. NO hagas preguntas de calificación (medidas, tipo de servicio, etc.) dentro del comentario público — esas se resuelven por ${canalEscalada}, no aquí

IMPORTANTE:
- La RESPUESTA debe ser corta (máximo 2 oraciones), apta para publicar directamente en el comentario/DM
- NO uses markdown, bullets ni emojis excesivos en la respuesta pública
${wa_link ? `- SIEMPRE incluye el link de WhatsApp tal cual: ${wa_link}` : '- Invita a escribir por mensaje privado, sin inventar ningún link ni número'}
- Sé cálido pero directo — el objetivo es mover la conversación a ${canalEscalada}, no resolverla en público
- Si hay CONTEXTO DEL POST COMENTADO, úsalo para que la micro-respuesta sea más relevante y específica

Entrega EXACTAMENTE en este formato:
INTENCIÓN: [informacional|comercial|transaccional]
RESPUESTA: [texto listo para publicar en redes${wa_link ? ', SIEMPRE con el link de WhatsApp incluido' : ''}]
LEAD: [frío|tibio|caliente]
PREGUNTA: [pregunta de calificación, se usará por ${canalEscalada}, no en el comentario]
SIGUIENTE PASO: [${siguientePasoValor}]`;

const mensajeUsuario = `Plataforma: ${evento.plataforma}
Tipo: ${evento.tipo}${seccionPost}
Mensaje del usuario: ${evento.mensaje}`;

return [{ json: {
  promptSistema,
  mensajeUsuario,
  evento,
  wa_link,
  empresa_nombre: nombre_empresa
}}];

