const usoZhipu = $('🤖 Zhipu: Fallback IA (Community AI)').isExecuted;
const raw = usoZhipu ? $('🤖 Zhipu: Fallback IA (Community AI)').first().json : $('🤖 Groq: Community AI').first().json;
const texto = raw.choices?.[0]?.message?.content || '';

const get = (label) => {
  const regex = new RegExp(`${label}[:\\s]+([^\\n]+)`, 'i');
  const match = texto.match(regex);
  return (match?.[1] || '').trim();
};

const intencion = get('INTENCI[OÓ]N');
const respuesta = get('RESPUESTA');
const lead = get('LEAD');
const pregunta = get('PREGUNTA');
const siguientePaso = get('SIGUIENTE PASO');

// La respuesta pública ya viene completa del prompt (incluye el link de WhatsApp una sola vez) —
// no se le agrega nada más aquí para evitar duplicar el link o repetir la pregunta de calificación.
const respuestaPublica = respuesta;

const evento = $('🔍 Extraer Evento FB/IG').item.json;

return [{ json: {
  intencion,
  respuesta,
  respuestaPublica,
  lead,
  pregunta,
  siguientePaso,
  plataforma: evento.plataforma,
  tipo: evento.tipo,
  comentarioId: evento.comentarioId,
  postId: evento.postId,
  mediaId: evento.mediaId,
  usuarioId: evento.usuarioId,
  usuarioNombre: evento.usuarioNombre,
  texto_completo_groq: texto
}}];

